<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useSessionStore } from '../../store/session'
import { api } from '../../api'
import { t } from '../../locales'
import '../../styles/app.scss'

const store = useSessionStore()
const profile = ref<any>({})
onMounted(async () => { if (store.token) { try { profile.value = await api.profile() } catch {} } })
function theme() { const modes = ['light', 'dark', 'system']; store.setTheme(modes[(modes.indexOf(store.theme) + 1) % modes.length]); uni.showToast({ title: t('主题已切换'), icon: 'none' }) }
const themeName = computed(() => store.theme === 'dark' ? t('深色模式') : store.theme === 'system' ? t('跟随系统') : t('浅色模式'))
async function logout() { try { await api.logoutRemote() } catch {} store.logout(); uni.reLaunch({ url: '/pages/index/index' }) }
function go(path: string) {
  const requiresAuth = ['/pages/me/profile', '/pages/me/favorites', '/pages/me/notifications', '/pages/me/security', '/pages/me/messages']
  if (!store.token && requiresAuth.some(prefix => path.startsWith(prefix))) return openLogin()
  uni.navigateTo({ url: path })
}
function openLogin() { uni.reLaunch({ url: '/pages/index/index?auth=login' }) }
function openRegister() { uni.navigateTo({ url: '/pages/auth/register' }) }
</script>
<template><view class="me-page"><view v-if="store.token" class="profile" @click="go('/pages/me/profile')"><view class="avatar">♙</view><view class="profile-info"><text class="profile-name">{{profile.nickname || profile.email || t('未设置资料')}}</text><text class="profile-email">{{profile.email || t('未绑定邮箱')}}</text></view><text class="chevron">›</text></view><view v-else class="profile guest-profile"><view class="avatar">♙</view><view class="profile-info"><text class="profile-name">{{t('游客模式')}}</text><text class="profile-email">{{t('登录后同步收藏与个人设置')}}</text></view><view class="guest-actions"><text @click="openLogin">{{t('登录')}}</text><text @click="openRegister">{{t('注册')}}</text></view></view><view class="menu-group"><view class="menu" @click="go('/pages/me/favorites')"><view><text class="menu-icon amber">☆</text><text>{{t('我的收藏')}}</text></view><text class="chevron">›</text></view><view class="menu" @click="go('/pages/me/contact')"><view><text class="menu-icon blue">▢</text><text>{{t('客服联系方式')}}</text></view><text class="chevron">›</text></view><view class="menu" @click="go('/pages/me/notifications')"><view><text class="menu-icon violet">♧</text><text>{{t('消息通知设置')}}</text></view><text class="chevron">›</text></view></view><view class="menu-group"><view class="menu" @click="theme"><view><text class="menu-icon gray">◐</text><text>{{t('主题模式')}}</text></view><text class="hint">{{themeName}}　›</text></view><view class="menu" @click="go('/pages/content/index')"><view><text class="menu-icon rose">△</text><text>{{t('风险提示')}}</text></view><text class="chevron">›</text></view><view class="menu" @click="go('/pages/content/static?type=about')"><view><text class="menu-icon green">ⓘ</text><text>{{t('关于我们')}}</text></view><text class="hint">{{t('版本信息')}}　›</text></view><view class="menu" @click="go('/pages/me/security')"><view><text class="menu-icon indigo">♢</text><text>{{t('安全设置')}}</text></view><text class="hint">{{t('修改密码 / 2FA　›')}}</text></view><view class="menu" @click="go('/pages/me/diagnostics')"><view><text class="menu-icon gray">≡</text><text>{{t('接口日志')}}</text></view><text class="hint">{{t('查看请求结果')}}　›</text></view></view><view class="menu-group secondary-group"><view class="menu" @click="go('/pages/me/messages')"><view><text class="menu-icon blue">✉</text><text>{{t('消息列表')}}</text></view><text class="chevron">›</text></view><view class="menu" @click="go('/pages/me/markets')"><view><text class="menu-icon green">⌁</text><text>{{t('完整行情')}}</text></view><text class="chevron">›</text></view></view><button v-if="store.token" class="logout" @click="logout">{{t('退出登录')}}</button></view></template>
<style scoped>.me-page{min-height:100vh;padding-bottom:150rpx;background:#F8FAFC;color:var(--cf-text)}.profile{display:flex;align-items:center;gap:18rpx;min-height:138rpx;padding:25rpx 28rpx;border-bottom:1rpx solid var(--cf-line);background:#fff}.avatar{display:grid;place-items:center;flex:0 0 66rpx;width:66rpx;height:66rpx;border-radius:50%;background:var(--cf-brand);color:#fff;font-size:37rpx}.profile-info{display:flex;flex:1;flex-direction:column;gap:4rpx;min-width:0}.profile-name{font-size:30rpx;font-weight:800}.profile-email{color:var(--cf-muted);font-size:22rpx}.guest-actions{display:flex;gap:12rpx}.guest-actions text{padding:12rpx 18rpx;border-radius:10rpx;background:#EFF6FF;color:var(--cf-brand);font-size:22rpx}.chevron{color:#CBD5E1;font-size:30rpx}.menu-group{margin:20rpx 25rpx 0;border:1rpx solid var(--cf-line);border-radius:12rpx;background:#fff;overflow:hidden}.menu{display:flex;align-items:center;justify-content:space-between;min-height:80rpx;padding:9rpx 16rpx;border-bottom:1rpx solid #F1F5F9;font-size:25rpx;font-weight:600}.menu:last-child{border:0}.menu>view{display:flex;align-items:center;gap:14rpx}.menu-icon{display:grid;place-items:center;flex:0 0 42rpx;width:42rpx;height:42rpx;border-radius:10rpx;font-size:27rpx}.menu-icon.amber{background:#FFFBEB;color:#F59E0B}.menu-icon.blue{background:#EFF6FF;color:#2563EB}.menu-icon.violet{background:#FAF5FF;color:#9333EA}.menu-icon.gray{background:#F1F5F9;color:#64748B}.menu-icon.rose{background:#FFF1F2;color:#F43F5E}.menu-icon.green{background:#ECFDF5;color:#10B981}.menu-icon.indigo{background:#EEF2FF;color:#4F46E5}.hint{color:var(--cf-soft);font-size:21rpx;font-weight:400}.secondary-group{margin-top:28rpx}.logout{display:block;width:calc(100% - 50rpx);min-height:82rpx;margin:24rpx auto 0;border:1rpx solid var(--cf-line);border-radius:12rpx;background:#fff;color:var(--cf-down);font-size:25rpx}</style>
